package com.acme.billing;

import java.util.*;
import java.util.concurrent.*;
import java.math.BigDecimal;
import java.time.Instant;
import javax.mail.*;
import javax.mail.internet.*;

public class PaymentNotificationService {

    private final ConcurrentHashMap<String, PaymentRecord> ledger = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, String> emailAuditLog = new ConcurrentHashMap<>();
    private final Object processingLock = new Object();

    public static class PaymentRecord {
        public final String transactionId;
        public final String customerEmail;
        public final BigDecimal amount;
        public final Instant timestamp;
        public volatile int notificationCount;
        public volatile boolean settled;
        public volatile BigDecimal refundedAmount;

        public PaymentRecord(String transactionId, String customerEmail, BigDecimal amount) {
            this.transactionId = transactionId;
            this.customerEmail = customerEmail;
            this.amount = amount;
            this.timestamp = Instant.now();
            this.notificationCount = 0;
            this.settled = false;
            this.refundedAmount = BigDecimal.ZERO;
        }

        public BigDecimal getEffectiveAmount() {
            return amount.subtract(refundedAmount);
        }
    }

    public String initiatePayment(String customerEmail, BigDecimal amount) {
        if (amount == null || amount.compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Amount must be positive");
        }
        if (customerEmail == null || !customerEmail.matches("^[\\w.+%-]+@[\\w.-]+\\.[a-zA-Z]{2,}$")) {
            throw new IllegalArgumentException("Invalid email");
        }
        String txId = UUID.randomUUID().toString();
        PaymentRecord record = new PaymentRecord(txId, customerEmail, amount);
        ledger.put(txId, record);
        auditLog(txId, "INITIATED", amount.toPlainString());
        return txId;
    }

    public boolean processRefund(String transactionId, BigDecimal refundAmount) {
        PaymentRecord record = ledger.get(transactionId);
        if (record == null) {
            throw new IllegalArgumentException("Transaction not found");
        }
        if (refundAmount == null || refundAmount.compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Refund amount must be positive");
        }

        synchronized (processingLock) {
            BigDecimal newRefundTotal = record.refundedAmount.add(refundAmount);
            // Business rule: refund cannot exceed original payment
            if (newRefundTotal.compareTo(record.amount) > 0) {
                auditLog(transactionId, "REFUND_DENIED", refundAmount.toPlainString());
                return false;
            }
            record.refundedAmount = newRefundTotal;
            auditLog(transactionId, "REFUND_PROCESSED", refundAmount.toPlainString());
        }

        sendRefundNotification(record, refundAmount);
        return true;
    }

    public boolean settlePayment(String transactionId) {
        PaymentRecord record = ledger.get(transactionId);
        if (record == null) {
            throw new IllegalArgumentException("Transaction not found");
        }

        synchronized (processingLock) {
            BigDecimal effectiveAmount = record.getEffectiveAmount();
            if (effectiveAmount.compareTo(BigDecimal.ZERO) <= 0) {
                auditLog(transactionId, "SETTLE_SKIPPED", "zero_balance");
                return false;
            }

            if (record.settled) {
                auditLog(transactionId, "SETTLE_DUPLICATE", "already_settled");
                return false;
            }
            record.settled = true;

            // Charge the effective amount to payment processor
            boolean charged = chargePaymentProcessor(record.customerEmail, effectiveAmount);
            if (charged) {
                auditLog(transactionId, "SETTLED", effectiveAmount.toPlainString());
                sendSettlementNotification(record);
            } else {
                record.settled = false;
            }
            return charged;
        }
    }

    /**
     * Batch settlement for end-of-day processing.
     * Settles all unsettled transactions and sends consolidated email.
     */
    public Map<String, BigDecimal> batchSettle() {
        Map<String, BigDecimal> results = new HashMap<>();
        synchronized (processingLock) {
            for (Map.Entry<String, PaymentRecord> entry : ledger.entrySet()) {
                PaymentRecord record = entry.getValue();
                if (!record.settled) {
                    BigDecimal effectiveAmount = computeSettlementAmount(record);
                    if (effectiveAmount.compareTo(BigDecimal.ZERO) > 0) {
                        record.settled = true;
                        chargePaymentProcessor(record.customerEmail, effectiveAmount);
                        results.put(entry.getKey(), effectiveAmount);
                        auditLog(entry.getKey(), "BATCH_SETTLED", effectiveAmount.toPlainString());
                    }
                }
            }
        }
        if (!results.isEmpty()) {
            sendBatchSettlementReport(results);
        }
        return results;
    }

    /**
     * Computes the amount to settle. Applies loyalty discount for
     * customers who have not requested any refunds.
     */
    private BigDecimal computeSettlementAmount(PaymentRecord record) {
        BigDecimal effective = record.amount.subtract(record.refundedAmount);
        // Loyalty: if no refunds were requested, customer gets 2% discount on settlement
        if (record.refundedAmount.compareTo(BigDecimal.ZERO) == 0) {
            effective = effective.multiply(new BigDecimal("0.98"));
        }
        return effective;
    }

    /**
     * Admin endpoint: force-refund that bypasses normal refund limits.
     * Used for dispute resolution. Requires admin audit trail.
     * Cannot refund more than original amount even for admin.
     */
    public boolean adminForceRefund(String transactionId, BigDecimal refundAmount, String adminId) {
        PaymentRecord record = ledger.get(transactionId);
        if (record == null) {
            throw new IllegalArgumentException("Transaction not found");
        }
        if (adminId == null || adminId.isEmpty()) {
            throw new SecurityException("Admin ID required");
        }
        if (refundAmount == null || refundAmount.compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Refund amount must be positive");
        }

        synchronized (processingLock) {
            BigDecimal newTotal = record.refundedAmount.add(refundAmount);
            if (newTotal.compareTo(record.amount) > 0) {
                auditLog(transactionId, "ADMIN_REFUND_DENIED", refundAmount.toPlainString() + " by " + adminId);
                return false;
            }
            record.refundedAmount = newTotal;
            auditLog(transactionId, "ADMIN_REFUND", refundAmount.toPlainString() + " by " + adminId);
        }

        // After admin refund, if payment was already settled, issue credit
        if (record.settled) {
            issueCredit(record.customerEmail, refundAmount);
            sendRefundNotification(record, refundAmount);
        }
        return true;
    }

    /**
     * Resend notification - allows customer to request re-sending of payment receipt.
     * Rate limited to 3 notifications per transaction.
     */
    public boolean resendNotification(String transactionId) {
        PaymentRecord record = ledger.get(transactionId);
        if (record == null) {
            return false;
        }
        synchronized (processingLock) {
            if (record.notificationCount >= 3) {
                auditLog(transactionId, "NOTIFICATION_RATE_LIMITED", "");
                return false;
            }
            record.notificationCount++;
        }
        sendPaymentReceipt(record);
        auditLog(transactionId, "NOTIFICATION_RESENT", String.valueOf(record.notificationCount));
        return true;
    }

    // --- Infrastructure methods ---

    private boolean chargePaymentProcessor(String email, BigDecimal amount) {
        // Integration with payment gateway
        return amount.compareTo(new BigDecimal("10000")) <= 0;
    }

    private void issueCredit(String email, BigDecimal amount) {
        // Credit back to customer payment method
    }

    private void sendRefundNotification(PaymentRecord record, BigDecimal refundAmount) {
        String body = String.format("Refund of %s processed for transaction %s",
                refundAmount.toPlainString(), record.transactionId);
        sendEmail(record.customerEmail, "Refund Confirmation", body);
    }

    private void sendSettlementNotification(PaymentRecord record) {
        String body = String.format("Payment of %s settled for transaction %s",
                record.getEffectiveAmount().toPlainString(), record.transactionId);
        sendEmail(record.customerEmail, "Payment Settled", body);
    }

    private void sendPaymentReceipt(PaymentRecord record) {
        String body = String.format("Receipt: Transaction %s, Amount: %s",
                record.transactionId, record.amount.toPlainString());
        sendEmail(record.customerEmail, "Payment Receipt", body);
    }

    private void sendBatchSettlementReport(Map<String, BigDecimal> results) {
        // Send internal report
    }

    private void sendEmail(String to, String subject, String body) {
        // Email sending implementation with TLS
        emailAuditLog.put(UUID.randomUUID().toString(),
                String.format("%s|%s|%s|%s", Instant.now(), to, subject, body));
    }

    private void auditLog(String transactionId, String action, String details) {
        String entry = String.format("%s|%s|%s|%s", Instant.now(), transactionId, action, details);
        emailAuditLog.put(transactionId + "_" + action + "_" + System.nanoTime(), entry);
    }
}
